mapper.select:
SELECT , c.CUSTOMER_NAME
FROM TBL_AR_BAD_DEBT_PROVISION p
LEFT JOIN TBL_AR_CUSTOMER c ON p.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
WHERE p.IS_DELETED = 0

    AND p.CUSTOMER_ID = #{param.customerId}


    AND c.CUSTOMER_NAME LIKE '%' || #{param.customerName} || '%'


    AND p.PROVISION_METHOD = #{param.provisionMethod}


    AND p.PROVISION_STATUS = #{param.provisionStatus}


    AND p.PROVISION_DATE >= #{param.provisionDateStart}


    AND p.PROVISION_DATE <= #{param.provisionDateEnd}


    AND p.TENANT_ID = #{param.tenantId}


    AND p.ORG_ID = #{param.orgId}


    AND p.BOOK_ID = #{param.bookId}

ORDER BY p.PROVISION_DATE DESC

SELECT , c.CUSTOMER_NAME FROM TBL_AR_BAD_DEBT_PROVISION p LEFT JOIN TBL_AR_CUSTOMER c ON p.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 WHERE p.IS_DELETED = 0
AND p.TENANT_ID = #{param.tenantId}
ORDER BY p.PROVISION_DATE DESC

SELECT 
FROM TBL_AR_BAD_DEBT_PROVISION p
WHERE p.IS_DELETED = 0
    AND p.CUSTOMER_ID = #{customerId}
    AND p.TENANT_ID = #{tenantId}
ORDER BY p.PROVISION_DATE DESC

SELECT 
FROM TBL_AR_BAD_DEBT_PROVISION p
WHERE p.IS_DELETED = 0
    AND p.PROVISION_DATE >= #{startDate}
    AND p.PROVISION_DATE <= #{endDate}
    AND p.TENANT_ID = #{tenantId}
ORDER BY p.PROVISION_DATE DESC

SELECT NVL(SUM(PROVISION_AMOUNT), 0)
FROM TBL_AR_BAD_DEBT_PROVISION
WHERE IS_DELETED = 0
    AND TENANT_ID = #{tenantId}
    AND PROVISION_DATE <= #{asOfDate}
    AND PROVISION_STATUS = 1
